package com.bank.incmgmt;

public class Incident {
    public enum State { DETECTED, TRIAGED, RESPONDING, MITIGATED, RESOLVED }

    private final String id;
    private final String summary;
    private State state = State.DETECTED;
    private String severity;            // SEV1..SEV3

    public Incident(String id, String summary) {
        this.id = id;
        this.summary = summary;
    }

    public String getId() { return id; }
    public String getSummary() { return summary; }
    public State getState() { return state; }
    public void setState(State s) { this.state = s; }
    public String getSeverity() { return severity; }
    public void setSeverity(String sev) { this.severity = sev; }
}
