package com.bank.incmgmt;

import java.util.List;

public class Postmortem {
    private final String incidentId;
    private final String whatHappened;
    private final String impact;
    private final String mitigation;
    private final List<String> actionItems;

    public Postmortem(String incidentId, String whatHappened, String impact,
                      String mitigation, List<String> actionItems) {
        this.incidentId = incidentId;
        this.whatHappened = whatHappened;
        this.impact = impact;
        this.mitigation = mitigation;
        this.actionItems = actionItems;
    }

    public String render() {
        StringBuilder sb = new StringBuilder();
        sb.append("Blameless Postmortem ").append(incidentId).append("\n");
        sb.append("  What happened: ").append(whatHappened).append("\n");
        sb.append("  Impact: ").append(impact).append("\n");
        sb.append("  Mitigation: ").append(mitigation).append("\n");
        sb.append("  Action items (systems, not people):\n");
        for (String a : actionItems) sb.append("    - ").append(a).append("\n");
        return sb.toString();
    }
}
