package com.bank.incmgmt;

import java.util.List;
import java.util.logging.Logger;

public class IncidentManager {
    private static final Logger log = Logger.getLogger(IncidentManager.class.getName());

    // Step 1: Detect
    public Incident detect(String id, String summary) {
        Incident inc = new Incident(id, summary);
        log.severe(() -> "[1 DETECT] alert fired: " + summary + " (" + id + ")");
        return inc;
    }

    // Step 2: Triage — assess severity + scope
    public void triage(Incident inc, int affectedUsers, boolean moneyMovementBroken) {
        String sev = moneyMovementBroken || affectedUsers > 10_000 ? "SEV1"
                   : affectedUsers > 1000 ? "SEV2" : "SEV3";
        inc.setSeverity(sev);
        inc.setState(Incident.State.TRIAGED);
        log.warning(() -> "[2 TRIAGE] " + sev + " — " + affectedUsers
            + " users affected, moneyMovementBroken=" + moneyMovementBroken);
    }

    // Step 3: Respond — assemble team + communicate
    public void respond(Incident inc) {
        inc.setState(Incident.State.RESPONDING);
        log.info(() -> "[3 RESPOND] " + inc.getSeverity()
            + ": incident commander assigned, responders paged, comms posting status page.");
    }

    // Step 4: Fix — MITIGATE FIRST, root-cause later
    public void mitigate(Incident inc, String action) {
        inc.setState(Incident.State.MITIGATED);
        log.info(() -> "[4 FIX] MITIGATE FIRST: " + action + " → service restored. "
            + "Root-cause analysis AFTER stability.");
    }

    // Step 5: Postmortem — blameless
    public Postmortem postmortem(Incident inc, String whatHappened, String impact,
                                 String mitigation, List<String> actionItems) {
        inc.setState(Incident.State.RESOLVED);
        Postmortem pm = new Postmortem(inc.getId(), whatHappened, impact, mitigation, actionItems);
        log.info(() -> "[5 POSTMORTEM] blameless review complete:\n" + pm.render());
        return pm;
    }
}
