package com.bank.incmgmt;

import java.util.List;
import java.util.logging.*;

public class IncidentManagementDemo {
    private static final Logger log = Logger.getLogger(IncidentManagementDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        IncidentManager mgr = new IncidentManager();

        Incident inc = mgr.detect("INC-2048",
            "transfer-api 5xx error rate spiked to 40% after deploy v6.0");
        mgr.triage(inc, 25_000, true);                 // many users, money broken → SEV1
        mgr.respond(inc);
        mgr.mitigate(inc, "rolled back transfer-api to v5.9 (kubectl rollout undo)");
        mgr.postmortem(inc,
            "Deploy v6.0 shipped a query that lost its index, spiking DB latency and 5xx.",
            "SEV1: ~25,000 customers could not transfer for 18 minutes; no data loss.",
            "Rolled back to v5.9; latency returned to baseline within 2 minutes.",
            List.of(
                "Add index-presence check to CI (catch the regression pre-deploy)",
                "Add canary with auto-rollback on 5xx regression",
                "Add DB latency SLO alert at burn-rate threshold"));
        log.info(() -> "Incident " + inc.getId() + " final state: " + inc.getState());
    }
}
